__factories["Identity"] = function(require)
-- Conservative hierarchy identity: no fuzzy name, size, or appearance matching.
local Identity = {}
local BUILTINS = { JumpButton = true, ThumbstickFrame = true, DynamicThumbstickFrame = true }
local function escaped(value) return tostring(value):gsub("%%", "%%25"):gsub("/", "%%2F"):gsub(":", "%%3A") end

function Identity.descriptor(instance, root)
    local path, ambiguous, current = {}, false, instance
    while current and current ~= root do
        local parent, ordinal, count = current.Parent, 0, 0
        if not parent then return nil, "Object is outside the discovery root" end
        for _, sibling in ipairs(parent:GetChildren()) do
            if sibling.Name == current.Name and sibling.ClassName == current.ClassName then
                count = count + 1
                if sibling == current then ordinal = count end
            end
        end
        if count > 1 then ambiguous = true end
        table.insert(path, 1, { name = current.Name, class = current.ClassName, ordinal = ordinal })
        current = parent
    end
    if current ~= root or #path == 0 then return nil, "Object is outside the discovery root" end
    local descriptor = { path = path, class = instance.ClassName }
    if ambiguous then descriptor.ambiguous = true end
    if #path == 3 and path[1].name == "TouchGui" and path[1].class == "ScreenGui"
        and path[2].name == "TouchControlFrame" and path[2].class == "Frame"
        and BUILTINS[path[3].name]
        and ((path[3].name == "JumpButton" and (instance.ClassName == "ImageButton" or instance.ClassName == "TextButton"))
            or (path[3].name ~= "JumpButton" and instance.ClassName == "Frame")) then
        descriptor.builtin = path[3].name
    end
    return descriptor
end

function Identity.key(descriptor)
    local parts = {}
    for i, segment in ipairs(descriptor.path or {}) do
        parts[i] = escaped(segment.name) .. ":" .. escaped(segment.class) .. ":" .. tostring(segment.ordinal or 1)
    end
    return table.concat(parts, "/")
end

local function samePath(a, b)
    if type(b) ~= "table" or type(b.path) ~= "table" or a.class ~= b.class or #a.path ~= #b.path then return false end
    for i, segment in ipairs(a.path) do
        local candidate = b.path[i]
        if segment.name ~= candidate.name or segment.class ~= candidate.class
            or (segment.ordinal or 1) ~= (candidate.ordinal or 1) then return false end
    end
    return true
end

function Identity.match(descriptor, candidates)
    if type(descriptor) ~= "table" or type(descriptor.path) ~= "table" then return nil, "Invalid identity" end
    if descriptor.ambiguous then return nil, "Ambiguous saved hierarchy; remap manually" end
    local found
    for i, candidate in ipairs(candidates) do
        if samePath(descriptor, candidate) then
            if found or candidate.ambiguous then return nil, "Ambiguous matching hierarchy; remap manually" end
            found = i
        end
    end
    if found then return found end
    return nil, "No exact hierarchy match"
end

return Identity
end

-- Module: Input
__factories["Input"] = function(require)
-- Heavenly Axis V3: shared touch/mouse gesture ownership.
-- Positions are InputObject.Position in physical screen pixels. The overlay uses
-- IgnoreGuiInset=true, so no per-event mouse/inset conversion is involved.
local Geometry = require("Geometry")
local Input = {}
Input.__index = Input

local function point(input)
    return {x = input.Position.X, y = input.Position.Y}
end
local function distance(a, b)
    local x, y = a.x - b.x, a.y - b.y
    return math.sqrt(x * x + y * y)
end
local function midpoint(a, b)
    return {x = (a.x + b.x) / 2, y = (a.y + b.y) / 2}
end
local function contains(rect, p, margin)
    margin = margin or 0
    return rect and p.x >= rect.x - margin and p.y >= rect.y - margin
        and p.x <= rect.x + rect.w + margin and p.y <= rect.y + rect.h + margin
end
local function selected(app, key)
    for _, value in ipairs(app.selection) do
        if value == key then return true end
    end
    return false
end
local function touch(input)
    return input.UserInputType == Enum.UserInputType.Touch
end
local function primary(input)
    return touch(input) or input.UserInputType == Enum.UserInputType.MouseButton1
end
local function cloneRects(rects)
    local result = {}
    for i, rect in ipairs(rects) do
        result[i] = {x = rect.x, y = rect.y, w = rect.w, h = rect.h}
    end
    return result
end

function Input.new(app, ui, services)
    local self = setmetatable({
        app = app, ui = ui, services = services, connections = {},
        gesture = nil, launcherGesture = nil, suppressed = {}, destroyed = false,
    }, Input)
    self.uis = services.UserInputService
    local function connect(signal, callback)
        self.connections[#self.connections + 1] = signal:Connect(callback)
    end
    connect(ui.canvas.InputBegan, function(input) self:_canvasBegin(input) end)
    for _, handle in ipairs(ui.handles) do
        connect(handle.gui.InputBegan, function(input)
            self:_transformBegin(input, "resize", handle.handle)
        end)
    end
    if ui.slider then
        connect(ui.slider.InputBegan, function(input) self:_transformBegin(input, "slider") end)
    end
    if ui.launcher then
        connect(ui.launcher.InputBegan, function(input) self:_launcherBegin(input) end)
    end
    connect(self.uis.InputChanged, function(input) self:_changed(input) end)
    connect(self.uis.InputEnded, function(input) self:_ended(input) end)
    connect(self.uis.InputBegan, function(input, processed) self:_key(input, processed) end)
    connect(self.uis.WindowFocusReleased, function() self:cancel() end)
