    self.ui:setGuides({})
end

function Input:_key(input, processed)
    if self.destroyed or input.UserInputType ~= Enum.UserInputType.Keyboard
        or self.uis:GetFocusedTextBox() then return end
    if self.ui.modalOpen then return end
    local prefs = self.app.preferences
    local shortcut = Enum.KeyCode.F8
    local valid, configured = pcall(function() return Enum.KeyCode[prefs.shortcut or "F8"] end)
    if valid and configured and configured ~= Enum.KeyCode.Unknown then shortcut = configured end
    if input.KeyCode == shortcut then
        if not processed then
            if self.app.editing then self:cancel() end
            self.app:setEditing(not self.app.editing)
        end
        return
    end
    if processed or not self.app.editing then return end
    local key = input.KeyCode
    if self.gesture then
        if key == Enum.KeyCode.Escape then self:cancel() end
        return
    end
    local control = self:_modifier("LeftControl") or self:_modifier("RightControl")
    local shift = self:_modifier("LeftShift") or self:_modifier("RightShift")
    if control then
        if key == Enum.KeyCode.Z then
            if shift then self.app:redo() else self.app:undo() end
        elseif key == Enum.KeyCode.Y then self.app:redo()
        elseif key == Enum.KeyCode.S then self.app:save() end
        return
    end
    if key == Enum.KeyCode.Escape then
        if self.gesture then self:cancel() else self.app:clearSelection() end
    elseif key == Enum.KeyCode.B then self.app:setPreference("boxSelect", not prefs.boxSelect)
    elseif key == Enum.KeyCode.Left then self.app:move(-(shift and 10 or prefs.step or 1), 0)
    elseif key == Enum.KeyCode.Right then self.app:move(shift and 10 or prefs.step or 1, 0)
    elseif key == Enum.KeyCode.Up then self.app:move(0, -(shift and 10 or prefs.step or 1))
    elseif key == Enum.KeyCode.Down then self.app:move(0, shift and 10 or prefs.step or 1) end
end

function Input:cancel()
    local gesture = self.gesture
    self.gesture, self.launcherGesture, self.suppressed = nil, nil, {}
    self.ui.launcherDragging = false
    if self.ui.positionLauncher then self.ui:positionLauncher() end
    if gesture and gesture.transaction then self.app:cancelGesture() end
    self.ui:setBox(nil)
    self.ui:setGuides({})
end
function Input:destroy()
    if self.destroyed then return end
    self:cancel()
    self.destroyed = true
    for _, connection in ipairs(self.connections) do connection:Disconnect() end
    self.connections = {}
end

return Input
end

-- Module: Profiles
__factories["Profiles"] = function(require)
local Config = require("Config")
local Util = require("Util")
local Profiles = {}
Profiles.__index = Profiles
local priorities = {global = 1, experience = 2, place = 3, device = 4, orientation = 5}

local function find(data, id)
    for index, profile in ipairs(data.profiles) do
        if profile.id == id then return profile, index end
    end
end

local function cleanName(name)
    if type(name) ~= "string" then return nil end
    name = name:match("^%s*(.-)%s*$")
    if #name == 0 or #name > 64 or name:find("[%c]") then return nil end
    return name
end

function Profiles.new(data, storage, context, log)
    data = data or Config.empty()
    local valid, reason = Config.validate(data)
    assert(valid, "Invalid initial configuration: " .. tostring(reason))
    data = Util.copy(data)
    data.preferences = data.preferences or {}
    return setmetatable({data = data, storage = storage, context = context, log = log or function() end, serial = 0, suspended = false}, Profiles)
end

function Profiles:list(allScopes)
    local profiles = {}
    for _, profile in ipairs(self.data.profiles) do
        if allScopes or Config.applies(profile, self.context) then profiles[#profiles + 1] = profile end
    end
    table.sort(profiles, function(a, b)
        if a.name == b.name then return a.id < b.id end
        return a.name:lower() < b.name:lower()
    end)
    return profiles
end

function Profiles:active()
    local current
    for _, profile in ipairs(self.data.profiles) do
        if Config.applies(profile, self.context) and self.data.active[Config.scopeKey(profile)] == profile.id then
            if not current or priorities[profile.scope] > priorities[current.scope]
                or (priorities[profile.scope] == priorities[current.scope] and profile.device ~= nil and current.device == nil) then current = profile end
        end
    end
    return current
end

function Profiles:_id()
    repeat
        self.serial = self.serial + 1
        local id = "profile-" .. tostring(os.time()) .. "-" .. tostring(self.serial)
        if not find(self.data, id) then return id end
    until false
end

function Profiles:create(name, scope)
    if self.preview then return nil, "Apply or cancel the preview before managing profiles." end
    name = cleanName(name)
    if not name then return nil, "Choose a profile name of 1–64 readable characters." end
    scope = scope or "place"
    if not priorities[scope] then return nil, "Unknown profile scope." end
    local profile = {id = self:_id(), name = name, scope = scope, layout = {}, groups = {}, preferences = {}}
    if scope == "experience" then profile.scopeId = self.context.experience end
    if scope == "place" or scope == "device" or scope == "orientation" then profile.scopeId = self.context.place end
    if scope == "device" or scope == "orientation" then profile.device = self.context.device end
    if scope == "orientation" then profile.orientation = self.context.orientation end
    local valid, err = Config.validateProfile(profile)
    if not valid then return nil, err end
    local candidate = Util.copy(self.data)
    candidate.profiles[#candidate.profiles + 1] = profile
    local accepted, reason = Config.validate(candidate)
    if not accepted then return nil, reason end
    self.data = candidate
    self.log("Created profile " .. name .. "; preview and Apply to activate, Save to persist.")
    return find(self.data, profile.id)
end

function Profiles:rename(id, name)
    if self.preview then return false, "Apply or cancel the preview before managing profiles." end
    name = cleanName(name)
    if not name then return false, "Choose a profile name of 1–64 readable characters." end
    local profile = find(self.data, id)
    if not profile then return false, "Profile not found." end
    profile.name = name
    return true, "Profile renamed in memory; Save to persist."
end

function Profiles:duplicate(id, name)
    if self.preview then return nil, "Apply or cancel the preview before managing profiles." end
    local source = find(self.data, id)
    if not source then return nil, "Profile not found." end
    name = cleanName(name or (source.name:sub(1, 58) .. " copy"))
    if not name then return nil, "Choose a profile name of 1–64 readable characters." end
    local profile = Util.copy(source)
    profile.id, profile.name = self:_id(), name
    local candidate = Util.copy(self.data)
    candidate.profiles[#candidate.profiles + 1] = profile
    local ok, reason = Config.validate(candidate)
    if not ok then return nil, reason end
    self.data = candidate
    return find(self.data, profile.id)
end

function Profiles:delete(id, confirmed)
    if confirmed ~= true then return false, "Confirm profile deletion. GUI elements and original layouts will be preserved." end
    if self.preview then return false, "Apply or cancel the profile preview first." end
    local profile, index = find(self.data, id)
    if not profile then return false, "Profile not found." end
    table.remove(self.data.profiles, index)
    for key, activeId in pairs(self.data.active) do
        if activeId == id then self.data.active[key] = nil end
    end
    return true, "Profile deleted in memory; Save to persist. GUI elements were preserved."
end

function Profiles:resolve()
    if self.suspended then return {}, Util.copy(self.data.preferences or {}), {} end
    return Config.resolve(self.data, self.context)
end

function Profiles:beginPreview(id)
    local profile = find(self.data, id)
    if not profile then return nil, "Profile not found." end
    if not Config.applies(profile, self.context) then return nil, "This profile belongs to another experience, place, device or orientation." end
    local candidate = Util.copy(self.data)
    local chosenKey = Config.scopeKey(profile)
    -- Selecting a layer explicitly makes it the editable layer for this context.
    -- Suspend more-specific active references in the preview candidate only;
    -- their profile definitions remain available for later reactivation.
    for _, other in ipairs(candidate.profiles) do
        local otherKey = Config.scopeKey(other)
        if Config.applies(other, self.context)
            and (priorities[other.scope] > priorities[profile.scope]
                or (other.scope == profile.scope and otherKey ~= chosenKey)) then
            candidate.active[otherKey] = nil
        end
    end
    candidate.active[chosenKey] = profile.id
    local valid, err = Config.validate(candidate)
    if not valid then return nil, err end
    local layout, preferences, groups = Config.resolve(candidate, self.context)
    self.preview = {kind = "profile", id = profile.id, data = candidate, preferences = preferences, groups = groups}
    return layout, nil, preferences, groups
end

function Profiles:applyPreview()
    if not self.preview then return false, "No profile preview to apply." end
    local valid, err = Config.validate(self.preview.data)
    if not valid then return false, err end
    self.data = Util.copy(self.preview.data)
    self.preview = nil
    self.suspended = false
    return true, "Profile preview applied in memory; Save to persist."
end

function Profiles:cancelPreview()
    self.preview = nil
    return true, "Preview canceled; active profile unchanged."
end

function Profiles:save(layout, groups, preferences)
    if self.preview then return false, "Apply or cancel the preview before saving." end
    local stateValid, stateReason = Config.validateProfile({id = "checkpoint", name = "Checkpoint", scope = "place", scopeId = self.context.place, layout = layout or {}, groups = groups or {}, preferences = preferences or {}})
    if not stateValid then return false, "Checkpoint rejected: " .. tostring(stateReason) end
    local candidate = Util.copy(self.data)
    local active = self:active()
    local profile
    if active then
        profile = find(candidate, active.id)
    else
        profile = {id = self:_id(), name = "Default place", scope = "place", scopeId = self.context.place, layout = {}, groups = {}, preferences = {}}
        candidate.profiles[#candidate.profiles + 1] = profile
        candidate.active[Config.scopeKey(profile)] = profile.id
    end
    -- App supplies the full authoritative state, including unresolved identities.
    -- Replacing here also preserves deliberate removals during manual remapping.
    profile.layout = Util.copy(layout or {})
    profile.groups, profile.preferences = Util.copy(groups or {}), Util.copy(preferences or {})
    local valid, reason = Config.validate(candidate)
    if not valid then return false, "Save rejected: " .. tostring(reason) .. ". Use a place profile for game-specific elements." end
    -- A valid in-memory checkpoint remains exportable even when persistence is unavailable.
    self.data = candidate
    local saved, message = self.storage:save(candidate)
    self.log(message)
    return saved, message, true
end

function Profiles:import(text)
    return self.storage:import(text)
end

function Profiles:beginImport(text, overwriteConfirmed)
    local incoming, err = self:import(text)
    if not incoming then return nil, err end
    local candidate = Util.copy(self.data)
    local conflicts = false
    for _, profile in ipairs(incoming.profiles) do
        local existing = find(candidate, profile.id)
        if existing and not Util.equal(existing, profile) then conflicts = true end
    end
    for key, value in pairs(incoming.preferences or {}) do
        if candidate.preferences[key] ~= nil and not Util.equal(candidate.preferences[key], value) then conflicts = true end
    end
    if conflicts and overwriteConfirmed ~= true then return nil, "Import would overwrite existing profiles or preferences. Confirm overwrite, then preview again." end
    for _, profile in ipairs(incoming.profiles) do
        local _, index = find(candidate, profile.id)
        if index then candidate.profiles[index] = Util.copy(profile) else candidate.profiles[#candidate.profiles + 1] = Util.copy(profile) end
    end
    for key, id in pairs(incoming.active) do candidate.active[key] = id end
    for key, value in pairs(incoming.preferences or {}) do candidate.preferences[key] = Util.copy(value) end
    local valid, reason = Config.validate(candidate)
    if not valid then return nil, "Merged import rejected: " .. tostring(reason) end
    local layout, preferences, groups = Config.resolve(candidate, self.context)
    self.preview = {kind = "import", data = candidate, preferences = preferences, groups = groups}
    return layout, nil, preferences, groups
end

function Profiles:export()
    return self.storage:export(self.data)
end

function Profiles:suspend(value)
    self.suspended = value == true
    return self.suspended
end

return Profiles
end

-- Module: Storage
__factories["Storage"] = function(require)
-- Versioned JSON only: imported content is never executed.
local Config = require("Config")
local Util = require("Util")
local Storage = {}
Storage.__index = Storage
Storage.FILES = {
    saved = "HeavenlyAxis-v3.json",
    backup = "HeavenlyAxis-v3.backup.json",
    pending = "HeavenlyAxis-v3.pending.json",
    draft = "HeavenlyAxis-v3.draft.json",
}
Storage.MAX_BYTES = 2 * 1024 * 1024

local function validateState(state)
    if type(state) ~= "table" then return false, "Draft must contain a state" end
    for key in pairs(state) do
        if key ~= "layout" and key ~= "groups" and key ~= "preferences" and key ~= "context" then return false, "Unknown draft field" end
    end
    if state.context ~= nil then
        if type(state.context) ~= "table" then return false, "Invalid draft context" end
        for key, value in pairs(state.context) do
            if key ~= "experience" and key ~= "place" and key ~= "device" and key ~= "orientation" then return false, "Unknown draft context field" end
            if type(value) ~= "string" or #value > 80 then return false, "Invalid draft context value" end
        end
    end
    return Config.validateProfile({id = "draft", name = "Unsaved draft", scope = "place", scopeId = "0", layout = state.layout or {}, groups = state.groups or {}, preferences = state.preferences or {}})
end

function Storage.new(capabilities, httpService, log, context)
    return setmetatable({capabilities = capabilities, http = httpService, log = log or function() end, blocked = false, context = context}, Storage)
end

function Storage:_draftPath(context)
    context = context or self.context
    if type(context) == "table" and type(context.experience) == "string" and type(context.place) == "string"
        and #context.experience <= 32 and #context.place <= 32
        and context.experience:match("^%d+$") and context.place:match("^%d+$")
        and (context.device == "touch" or context.device == "desktop")
        and (context.orientation == "portrait" or context.orientation == "landscape") then
        return "HeavenlyAxis-v3.draft." .. context.experience .. "." .. context.place .. "." .. context.device .. "." .. context.orientation .. ".json"
    end
    return self.FILES.draft
end

function Storage:_available()
    local f = self.capabilities._functions or {}
    return type(f.readfile) == "function" and type(f.writefile) == "function" and type(f.isfile) == "function"
end

function Storage:_fail(message)
    self.capabilities.storage.status = "Failed"
    self.capabilities.storage.detail = message
    self.log(message)
    return false, message
end

function Storage:_exists(path)
    local ok, exists = pcall(self.capabilities._functions.isfile, path)
    if not ok or type(exists) ~= "boolean" then return nil, "File availability check failed; existing files preserved." end
    return exists
end

function Storage:_decode(text)
    if type(text) ~= "string" or #text == 0 or #text > self.MAX_BYTES then return nil, "JSON is empty or exceeds the size limit." end
    if not self.http then return nil, "JSON service unavailable." end
    local ok, value = pcall(function() return self.http:JSONDecode(text) end)
    if not ok or type(value) ~= "table" then return nil, "Malformed JSON." end
    return value
end

function Storage:_encode(value)
    if not self.http then return nil, "JSON service unavailable." end
    local ok, text = pcall(function() return self.http:JSONEncode(value) end)
    if not ok or type(text) ~= "string" or #text > self.MAX_BYTES then return nil, "JSON encoding failed or exceeds the size limit." end
    return text
end

function Storage:import(text)
    local data, err = self:_decode(text)
    if not data then return nil, err end
    local ok, reason = Config.validate(data)
    if not ok then return nil, "Invalid configuration: " .. tostring(reason) end
    return Util.copy(data)
end

function Storage:export(data)
    local ok, err = Config.validate(data)
    if not ok then return nil, "Invalid configuration: " .. tostring(err) end
    return self:_encode(data)
end

function Storage:_read(path)
    local exists, err = self:_exists(path)
    if exists == nil then return nil, err end
    if not exists then return nil, "missing" end
    local ok, raw = pcall(self.capabilities._functions.readfile, path)
    if not ok or type(raw) ~= "string" then return nil, "Local file read failed; existing files preserved." end
    return raw
end

function Storage:load()
    if not self:_available() then return nil, "Persistent storage unavailable; profiles stay in memory until exported." end
    local raw, err = self:_read(self.FILES.saved)
    if not raw and err == "missing" then return nil, "No saved V3 configuration." end
    local data, reason
    if raw then data, reason = self:import(raw) else reason = err end
    if data then
        self.capabilities.storage.status = "Available but unverified"
        self.capabilities.storage.detail = "Saved JSON read and validated; next Save verifies writes."
        return data
    end
    self.blocked = true
    local backup = self:_read(self.FILES.backup)
    local recovered = backup and self:import(backup)
    local message = recovered and "Loaded valid backup in memory. Damaged saved file preserved; export before repairing storage manually." or "Saved configuration could not be validated. Original file preserved; Save is blocked until it is repaired or moved manually."
    self:_fail(message)
    return recovered, reason or message
end

function Storage:_verifiedWrite(path, raw)
    local ok = pcall(self.capabilities._functions.writefile, path, raw)
    if not ok then return false end
    local readOk, actual = pcall(self.capabilities._functions.readfile, path)
    return readOk and actual == raw
end

function Storage:save(data)
    local raw, err = self:export(data)
    if not raw then return false, err end
    if not self:_available() then return false, "Checkpoint is in memory only. Export JSON for a durable copy." end
    if self.blocked then return self:_fail("Save blocked: existing configuration needs manual repair. Export JSON to preserve this checkpoint.") end
    -- Validate every existing primary before any overwrite, including saves before load.
    local previous, readError = self:_read(self.FILES.saved)
    if not previous and readError ~= "missing" then return self:_fail(readError) end
    if previous then
        local valid = self:import(previous)
        if not valid then
            self.blocked = true
            return self:_fail("Save blocked: existing configuration is invalid. It has been preserved; export JSON instead.")
        end
    end
    if not self:_verifiedWrite(self.FILES.pending, raw) then return self:_fail("Save failed while staging configuration; previous save preserved.") end
    if previous and not self:_verifiedWrite(self.FILES.backup, previous) then return self:_fail("Save failed while preserving backup; previous save preserved.") end
    if not self:_verifiedWrite(self.FILES.saved, raw) then
        if previous then pcall(self.capabilities._functions.writefile, self.FILES.saved, previous) end
        return self:_fail("Save failed during final write. Previous backup and staged checkpoint remain available; export JSON.")
    end
    local remove = self.capabilities._functions.delfile
    if type(remove) == "function" then pcall(remove, self.FILES.pending) end
    self.capabilities.storage.status = "Supported and verified"
    self.capabilities.storage.detail = "Last Save wrote and read back validated JSON."
    return true, "Profile persisted locally and verified by readback. Automatic execution must be configured separately."
end

function Storage:draft(state)
    state = Util.copy(state)
    if type(state) == "table" and self.context then
        if state.context and not Util.equal(state.context, self.context) then return false, "Draft context changed before recording; previous recovery preserved." end
        state.context = Util.copy(self.context)
    end
    local valid, reason = validateState(state)
    if not valid then return false, "Invalid draft: " .. tostring(reason) end
    if not self:_available() then return false, "Draft recovery unavailable without local storage." end
    local raw, err = self:_encode({version = Config.VERSION, draft = true, state = state})
    if not raw then return false, err end
    -- A corrupt draft is also user data; keep it until explicitly cleared.
    local path = self:_draftPath()
    local previous, readError = self:_read(path)
    if not previous and readError ~= "missing" then return false, readError end
    if previous then
        local old = self:_decode(previous)
        if not old or old.version ~= Config.VERSION or (old.draft ~= false and (old.draft ~= true or not validateState(old.state))) then return false, "Damaged draft preserved; clear it explicitly before recording another draft." end
        if old.draft == true and not Util.equal(old.state.context, state.context) then return false, "Recovery draft from another context preserved; discard it explicitly before recording another draft." end
    end
    if not self:_verifiedWrite(path, raw) then return false, "Draft write failed." end
    return true, "Unsaved draft recorded separately from profiles."
end

function Storage:loadDraft()
    if not self:_available() then return nil, "Draft recovery unavailable without local storage." end
    local raw, err = self:_read(self:_draftPath())
    if not raw then return nil, err end
    local value, reason = self:_decode(raw)
    if not value then return nil, reason end
    if value.version == Config.VERSION and value.draft == false then return nil, "No recoverable draft." end
    if value.version ~= Config.VERSION or value.draft ~= true then return nil, "Incompatible draft." end
    local valid, why = validateState(value.state)
    if not valid then return nil, "Invalid draft: " .. tostring(why) end
    return Util.copy(value.state)
end

function Storage:clearDraft(context)
    if not self:_available() then return false, "Draft storage unavailable." end
    local path = self:_draftPath(context)
    local exists, err = self:_exists(path)
    if exists == nil then return false, err end
    if not exists then return true, "No draft to clear." end
    local remove = self.capabilities._functions.delfile
    if type(remove) ~= "function" then
        local raw, encodeError = self:_encode({version = Config.VERSION, draft = false})
        if not raw then return false, encodeError end
        if self:_verifiedWrite(path, raw) then return true, "Draft discarded; saved profiles preserved." end
        return false, "Draft could not be discarded."
    end
    local ok = pcall(remove, path)
    local remaining = self:_exists(path)
    if not ok or remaining ~= false then return false, "Draft could not be deleted." end
    return true, "Draft discarded; saved profiles preserved."
end

function Storage:copy(text)
    if type(text) ~= "string" or #text > self.MAX_BYTES then return false, "Invalid clipboard content." end
    if type(self.capabilities._clipboard) ~= "function" then return false, "Clipboard unavailable; manually copy the JSON field." end
    local ok = pcall(self.capabilities._clipboard, text)
    self.capabilities.clipboard.status = ok and "Supported and verified" or "Failed"
    self.capabilities.clipboard.detail = ok and "Clipboard API accepted the export; paste to verify destination." or "Clipboard call failed; manually copy the JSON field."
    return ok, self.capabilities.clipboard.detail
end

return Storage
end

-- Module: Transform
__factories["Transform"] = function(require)
-- Screen-space transforms adapt only accessible GuiObject properties, never Roblox movement code.
local Util = require("Util")
local Identity = require("Identity")
local Discovery = require("Discovery")

local Transform = {}
Transform.__index = Transform

local function isA(object, class)
    local ok, result = pcall(function() return object:IsA(class) end)
    return ok and result
end

local function udim(value)
    return UDim2.new(value.xs, value.xo, value.ys, value.yo)
end

local function validDimension(value)
    if type(value) ~= "table" then return false end
    for _, key in ipairs({"xs", "xo", "ys", "yo"}) do
        if not Util.finite(value[key]) or math.abs(value[key]) > 1000000 then return false end
    end
    return true
end

local function validEntry(entry)
    if type(entry) ~= "table" or not validDimension(entry.position) or not validDimension(entry.size) then return false end
    if entry.rotation ~= nil and (not Util.finite(entry.rotation) or math.abs(entry.rotation) > 36000) then return false end
    if entry.transparency ~= nil and (not Util.finite(entry.transparency) or entry.transparency < 0 or entry.transparency > 1) then return false end
    return true
end

local function close(a, b)
    return math.abs(a - b) < 0.05
end

local function equivalent(object, entry)
    local actual = Discovery.serialize(object)
    if not actual then return false end
    for _, property in ipairs({"position", "size"}) do
        for _, axis in ipairs({"xs", "xo", "ys", "yo"}) do
            if not close(actual[property][axis], entry[property][axis]) then return false end
        end
    end
    if entry.rotation ~= nil and not close(actual.rotation, entry.rotation) then return false end
    if entry.transparency ~= nil and not close(actual.transparency, entry.transparency) then return false end
    return true
end

local function write(object, entry)
    object.Position, object.Size = udim(entry.position), udim(entry.size)
    if entry.rotation ~= nil then object.Rotation = entry.rotation end
    if entry.transparency ~= nil then object.BackgroundTransparency = entry.transparency end
end

local function directScale(object)
    local factor = 1
    for _, child in ipairs(object:GetChildren()) do
        if isA(child, "UIScale") then factor = factor * child.Scale end
    end
    return factor
end

local function scales(object, root)
    local positionScale, current = 1, object.Parent
    while current and current ~= root do
        if isA(current, "GuiObject") then positionScale = positionScale * directScale(current) end
        current = current.Parent
    end
    return positionScale, positionScale * directScale(object)
end

local function depth(record)
    return #record.descriptor.path
end

local function effectiveDimensions(object, size, root)
    local parent = object.Parent
    local parentSize = parent and parent.AbsoluteSize
    if not parentSize then return nil, nil end
    local positionScale = scales(object, root)
    local own = directScale(object)
    local basisX, basisY = parentSize.X, parentSize.Y
    local constraint = tostring(object.SizeConstraint)
    if constraint == "Enum.SizeConstraint.RelativeXX" or constraint == "RelativeXX" then basisY = basisX end
    if constraint == "Enum.SizeConstraint.RelativeYY" or constraint == "RelativeYY" then basisX = basisY end
    return (basisX * size.xs + size.xo * positionScale) * own,
        (basisY * size.ys + size.yo * positionScale) * own
end

local function rollbackEntry(operation)
    local entry = Util.copy(operation.previousTracked or operation.before)
    entry.descriptor = Util.copy(operation.record.descriptor)
    entry.experimental = operation.record.experimentalApproved == true or nil
    return entry
end

function Transform.new(discovery, log)
    return setmetatable({discovery = discovery, log = log or function() end, tracked = {},
        receipts = setmetatable({}, {__mode = "k"}), safe = false, generation = 0, destroyed = false}, Transform)
end

function Transform:_record(key, entry)
    local record = self.discovery:get(key)
    if record and not record.descriptor.ambiguous then return record end
    if not entry or not entry.descriptor then return nil end
    local candidates, records = {}, {}
    for _, candidate in pairs(self.discovery.records) do
        candidates[#candidates + 1], records[#records + 1] = candidate.descriptor, candidate
    end
    local index = Identity.match(entry.descriptor, candidates)
    return index and records[index] or nil
end

function Transform:_allowed(record, entry, options)
    if not record or not record.object.Parent then return false, "Element is missing" end
    self.discovery:_classify(record)
    if record.descriptor.ambiguous then return false, record.reason end
    if record.experimental then
        if self.safe or (options and options.safe) then return false, "Safe Mode blocks experimental overrides" end
        if record.experimentalSuspended then return false, record.reason end
        local savedApproval = options and options.experimental and entry and entry.experimental == true
        if savedApproval then
            self.discovery.approved[record.key] = true
            record.experimentalApproved = true
            self.discovery:_classify(record)
        end
        if not record.experimentalApproved then return false, record.reason end
    end
    if not record.editable then return false, record.reason or "Unsupported transformation" end
    return true
end

function Transform:_failed(record, reason)
    record.failures = (record.failures or 0) + 1
    if record.experimental and record.failures >= 3 then record.experimentalSuspended = true end
    self.discovery:_classify(record)
    local label = record.experimentalSuspended and "Experimental override suspended" or "Transform failed"
    self.log(label .. " (" .. tostring(record.object.Name) .. "): " .. tostring(reason):sub(1, 160))
end

function Transform:_stabilize(operations, generation)
    if #operations == 0 or not task or not task.delay then return end
    -- Debounce pointer updates into one quiet-period observation. At most one timer is pending.
    self.pendingStabilization = {operations = operations, generation = generation}
    if self.stabilizationScheduled then return end
    self.stabilizationScheduled = true
    local observe
    observe = function(expectedGeneration)
        if self.destroyed then self.pendingStabilization, self.stabilizationScheduled = nil, false return end
        local pending = self.pendingStabilization
        if not pending then self.stabilizationScheduled = false return end
        if pending.generation ~= expectedGeneration then
            task.delay(0.15, function() observe(pending.generation) end)
            return
        end
        self.pendingStabilization, self.stabilizationScheduled = nil, false
        if self.generation ~= pending.generation then return end
        local failed = false
        for _, operation in ipairs(pending.operations) do
            local object = operation.record.object
            local stable = not object.Parent or equivalent(object, operation.after)
            if object.Parent and stable and operation.expectedRect then
                local p, size = object.AbsolutePosition, object.AbsoluteSize
                local rect = operation.expectedRect
                stable = math.abs(p.X - rect.x) <= 1 and math.abs(p.Y - rect.y) <= 1
                    and math.abs(size.X - rect.w) <= 1 and math.abs(size.Y - rect.h) <= 1
            end
            if object.Parent and not stable then
                failed = true
                operation.record.managedByScript = true
                self.discovery:_classify(operation.record)
                self:_failed(operation.record, "Game or layout replaced the requested properties during stabilization")
            end
        end
        if failed then
            for _, operation in ipairs(pending.operations) do
                if operation.record.object.Parent then pcall(write, operation.record.object, operation.before) end
                self.tracked[operation.record.key] = rollbackEntry(operation)
                self.receipts[operation.record.object] = rollbackEntry(operation)
            end
            self.log("Unstable transaction rolled back; no layout enforcement loop is running")
            if self.onChanged then pcall(self.onChanged) end
        end
    end
    task.delay(0.15, function() observe(generation) end)
end

function Transform:beginTransaction()
    self.transaction = {initial = {}, operations = {}}
end

function Transform:_queueOperations(operations)
    if not self.transaction then self:_stabilize(operations, self.generation) return end
    for _, operation in ipairs(operations) do
        local key = operation.record.key
        local initial = self.transaction.initial[key]
        if not initial then
            initial = {before = Util.copy(operation.before), previousTracked = Util.copy(operation.previousTracked)}
            self.transaction.initial[key] = initial
        end
        self.transaction.operations[key] = {
            record = operation.record, before = initial.before, previousTracked = initial.previousTracked,
            after = operation.after, expectedRect = operation.expectedRect,
        }
    end
end

function Transform:endTransaction()
    if not self.transaction then return end
    local operations = {}
    for _, operation in pairs(self.transaction.operations) do operations[#operations + 1] = operation end
    self.transaction = nil
    self:_stabilize(operations, self.generation)
end

function Transform:cancelTransaction()
    self.transaction = nil
    self.generation = self.generation + 1
end

function Transform:capture()
    local result = {}
    for key, entry in pairs(self.tracked) do
        local record = self:_record(key, entry)
        if record then
            local snapshot = Discovery.serialize(record.object)
            if snapshot then
                snapshot.descriptor = Util.copy(record.descriptor)
                snapshot.experimental = record.experimentalApproved == true or nil
                if entry.viewport then snapshot.viewport = Util.copy(entry.viewport) end
                result[key] = snapshot
            end
        end
    end
    return result
end

function Transform:selectionRects(keys)
    local selected, objects = {}, {}
    for _, key in ipairs(keys or {}) do
        local record = self.discovery:get(key)
        if record and not selected[key] then selected[key] = record; objects[record.object] = true end
    end
    local rects, roots = {}, {}
    for _, key in ipairs(keys or {}) do
        local record = selected[key]
        if record then
            local nested, parent = false, record.object.Parent
            while parent and parent ~= self.discovery.root do
                if objects[parent] then nested = true break end
                parent = parent.Parent
            end
            if not nested then
                local ok, rect = pcall(function()
                    local p, s = record.object.AbsolutePosition, record.object.AbsoluteSize
                    return {x = p.X, y = p.Y, w = s.X, h = s.Y}
                end)
                if ok then rects[#rects + 1], roots[#roots + 1] = rect, key end
            end
            selected[key] = nil
        end
    end
    return rects, roots
end

function Transform:setRects(keys, rects)
    if self.destroyed then return false, "Transform controller is closed" end
    if #keys ~= #rects or #keys == 0 then return false, "No valid selection" end
    local roots, rootKeys = self:selectionRects(keys)
    if #rootKeys ~= #keys then return false, "Select parent roots before transforming nested objects" end
    local operations = {}
    for i, key in ipairs(keys) do
        local record, rect = self.discovery:get(key), rects[i]
        local allowed, reason = self:_allowed(record)
        if not allowed then return false, reason end
        if type(rect) ~= "table" then return false, "Invalid dimensions" end
        for _, axis in ipairs({"x", "y", "w", "h"}) do
            if not Util.finite(rect[axis]) or math.abs(rect[axis]) > 1000000 then return false, "Invalid dimensions" end
        end
        if rect.w < 16 or rect.h < 16 then return false, "Minimum size is 16 screen pixels" end
        local ok, operation = pcall(function()
            local object = record.object
            if math.abs(object.Rotation % 360) > 0.001 then error("Reset rotation to zero before screen-space resizing") end
            local positionScale, sizeScale = scales(object, self.discovery.root)
            if not Util.finite(positionScale) or positionScale <= 0 or not Util.finite(sizeScale) or sizeScale <= 0 then error("Invalid UIScale") end
            local before, after = Discovery.serialize(object), Discovery.serialize(object)
            if not before or not after then error("Properties inaccessible") end
            local p, s, anchor = object.AbsolutePosition, object.AbsoluteSize, object.AnchorPoint
            after.position.xo = before.position.xo + (rect.x - p.X + anchor.X * (rect.w - s.X)) / positionScale
            after.position.yo = before.position.yo + (rect.y - p.Y + anchor.Y * (rect.h - s.Y)) / positionScale
            after.size.xo = before.size.xo + (rect.w - s.X) / sizeScale
            after.size.yo = before.size.yo + (rect.h - s.Y) / sizeScale
            after.descriptor, after.experimental = Util.copy(record.descriptor), record.experimentalApproved == true or nil
            return {record = record, before = before, after = after, previousTracked = self.tracked[key],
                previousReceipt = self.receipts[record.object], expectedRect = Util.copy(rect)}
        end)
        if not ok then return false, tostring(operation):gsub("^.-:%d+: ", "") end
        operations[#operations + 1] = operation
    end
    self.generation = self.generation + 1
    for _, operation in ipairs(operations) do
        local ok, errorMessage = pcall(function()
            write(operation.record.object, operation.after)
            if not equivalent(operation.record.object, operation.after) then error("Requested properties were rejected") end
        end)
        if not ok then
            for _, rollback in ipairs(operations) do
                pcall(write, rollback.record.object, rollback.before)
                self.tracked[rollback.record.key] = rollback.previousTracked
                self.receipts[rollback.record.object] = rollback.previousReceipt
            end
            self:_failed(operation.record, errorMessage)
            return false, "Transform rejected; entire selection restored"
        end
        self.tracked[operation.record.key] = Util.copy(operation.after)
        self.receipts[operation.record.object] = Util.copy(operation.after)
    end
    self:_queueOperations(operations)
    return true
end

function Transform:apply(layout, options)
    options = options or {}
    if self.destroyed or type(layout) ~= "table" then return 0, 0 end
    local applied, skipped, operations, pending = 0, 0, {}, {}
    if options.replace then
        self.generation = self.generation + 1
        -- Permissions are part of the saved layout/checkpoint, so Undo and profile replacement
        -- revoke absent approvals rather than retaining a permission from the previous profile.
        for key in pairs(self.discovery.approved) do
            if not layout[key] or layout[key].experimental ~= true then
                self.discovery.approved[key] = nil
                local record = self.discovery:get(key)
                if record then self.discovery:_classify(record) end
            end
        end
        for key, entry in pairs(self.tracked) do
            if not layout[key] then
                local record = self:_record(key, entry)
                if record then
                    local ok = pcall(write, record.object, record.baseline)
                    if ok then self.receipts[record.object] = Util.copy(record.baseline)
                    else self.log("Original properties could not be restored for " .. tostring(record.object.Name)) end
                end
            end
        end
        self.tracked = {}
    end
    for key, entry in pairs(layout) do
        local record = self:_record(key, entry)
        if options.onlyNew and record and Util.equal(self.receipts[record.object], entry) then
            -- Structural/visibility events restore new instances only. Never re-enforce a
            -- previously applied request against an existing object's game scripts.
        elseif not validEntry(entry) then
            skipped = skipped + 1
            self.log("Skipped invalid layout properties")
        elseif not record then
            skipped = skipped + 1
        else
            if entry.experimental == false then
                self.discovery.approved[record.key] = nil
                self.discovery:_classify(record)
                if record.experimental then
                    -- Revocation restores the baseline once. Remember the handled
                    -- request even though this target is now intentionally skipped,
                    -- so unrelated HUD events cannot repeatedly fight its layout.
                    local restored = pcall(write, record.object, record.baseline)
                    self.receipts[record.object] = Util.copy(entry)
                    if not restored then self.log("Original properties unavailable while revoking experimental approval") end
                end
            end
            local allowed, reason = self:_allowed(record, entry, options)
            if allowed and not Util.equal(entry.size, record.baseline.size) then
                local dimensionOK, width, height = pcall(effectiveDimensions, record.object, entry.size, self.discovery.root)
                if not dimensionOK or not Util.finite(width) or not Util.finite(height)
                    or width < 16 or height < 16 or width > 1000000 or height > 1000000 then
                    allowed, reason = false, "Saved dimensions fall outside the supported 16–1000000 screen-pixel range"
                end
            end
            if not allowed then
                skipped = skipped + 1
                self.log("Skipped " .. tostring(record.object.Name) .. ": " .. tostring(reason))
            else pending[#pending + 1] = {record = record, entry = entry} end
        end
    end
    table.sort(pending, function(a, b) return depth(a.record) < depth(b.record) end)
    if not options.replace and #pending > 0 then self.generation = self.generation + 1 end
    for _, item in ipairs(pending) do
        local record, entry = item.record, item.entry
        local before = Discovery.serialize(record.object)
        local after = Util.copy(entry)
        local previousTracked = self.tracked[record.key]
        local ok, err = pcall(function()
            write(record.object, entry)
            if not equivalent(record.object, entry) then error("Requested properties were rejected") end
        end)
        if ok then
            applied = applied + 1
            self.tracked[record.key] = after
            self.receipts[record.object] = Util.copy(after)
            operations[#operations + 1] = {record = record, before = before, after = after, previousTracked = previousTracked}
        else
            skipped = skipped + 1
            if before then pcall(write, record.object, before) end
            self:_failed(record, err)
        end
    end
    self:_queueOperations(operations)
    return applied, skipped
end

function Transform:restore(keys)
    self.generation = self.generation + 1
    local restored, failed = 0, 0
    local targets = keys
    if not targets then
        targets = {}
        for key in pairs(self.tracked) do targets[#targets + 1] = key end
    end
    for _, key in ipairs(targets) do
        local record = self:_record(key, self.tracked[key])
        if record then
            local ok = pcall(write, record.object, record.baseline)
            if ok then
                restored = restored + 1
                local entry = Util.copy(record.baseline)
                entry.descriptor = Util.copy(record.descriptor)
                self.tracked[key] = entry
                self.receipts[record.object] = Util.copy(entry)
            else failed = failed + 1 end
        else failed = failed + 1 end
    end
    if failed > 0 then self.log(tostring(failed) .. " original elements unavailable during restoration") end
    return restored, failed
end

function Transform:matches(layout)
    local result = {}
    for key, entry in pairs(layout or {}) do
        if not self:_record(key, entry) then result[#result + 1] = {key = key, descriptor = Util.copy(entry.descriptor), reason = "No unique exact hierarchy match; manual remapping required"} end
    end
    table.sort(result, function(a, b) return a.key < b.key end)
    return result
end

function Transform:clearTracked()
    self.tracked = {}
end

function Transform:destroy()
    self.destroyed, self.generation, self.tracked = true, self.generation + 1, {}
    self.pendingStabilization, self.stabilizationScheduled, self.transaction = nil, false, nil
    self.receipts = setmetatable({}, {__mode = "k"})
end

return Transform
end

-- Module: UI
__factories["UI"] = function(require)
-- Heavenly Axis V3 — Roblox HUD & Interface Editor
-- Original project by Syshi; V2 inspired by Danechka.
local Geometry = require("Geometry")
local UI = {}
UI.__index = UI

local C = {
    surface = Color3.fromRGB(15, 23, 32), raised = Color3.fromRGB(26, 38, 50),
    cyan = Color3.fromRGB(82, 217, 233), text = Color3.fromRGB(233, 242, 247),
    muted = Color3.fromRGB(161, 180, 194), border = Color3.fromRGB(55, 79, 94),
    warning = Color3.fromRGB(255, 195, 108), danger = Color3.fromRGB(211, 105, 111),
}
local function make(class, props, parent)
    local object = Instance.new(class)
    for name, value in pairs(props or {}) do object[name] = value end
    object.Parent = parent
    return object
end
local function corners(object, radius)
    make("UICorner", {CornerRadius = UDim.new(0, radius or 8)}, object)
end
local function outline(object, color, thickness)
    return make("UIStroke", {Color = color or C.border, Thickness = thickness or 1, Transparency = .2}, object)
end
local function label(parent, text, height, size)
    return make("TextLabel", {Name = "Label", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, height or 30),
        Text = text, Font = Enum.Font.Gotham, TextSize = size or 13, TextColor3 = C.text,
        TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 24}, parent)
end
local function frame(parent, height)
    return make("Frame", {BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, height or 44), ZIndex = 23}, parent)
end
local function flow(parent, spacing)
    return make("UIListLayout", {SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, spacing or 7)}, parent)
end
local function selected(keys, key)
    for _, value in ipairs(keys or {}) do if value == key then return true end end
    return false
end
local function numberText(value)
    return string.format("%.1f", value or 0):gsub("%.0$", "")
end
local function inside(object, x, y)
    if not object or not object.Visible then return false end
    local p, s = object.AbsolutePosition, object.AbsoluteSize
    return x >= p.X and y >= p.Y and x <= p.X + s.X and y <= p.Y + s.Y
end

function UI:connect(signal, fn, dynamic)
    local connection = signal:Connect(function(...)
        if self.dead then return end
        local ok, problem = pcall(fn, ...)
        if not ok then self.app:log("Editor interaction failed: " .. tostring(problem)); self.app:status("That interaction failed; see diagnostics.") end
    end)
    table.insert(dynamic or self.connections, connection)
    return connection
end

function UI:button(parent, text, callback, width, x, color, dynamic)
    local b = make("TextButton", {Name = text:gsub("[^%w]", ""), Text = text, Size = UDim2.new(width or 1, width and -5 or 0, 0, 42),
        Position = UDim2.new(x or 0, 0, 0, 0), BackgroundColor3 = color or C.raised, BorderSizePixel = 0,
        TextColor3 = C.text, TextSize = 12, Font = Enum.Font.GothamMedium, TextWrapped = true,
        AutoButtonColor = true, ZIndex = parent.ZIndex + 1}, parent)
    corners(b, 7)
    outline(b)
    if callback then self:connect(b.Activated, callback, dynamic) end
    return b
end

function UI:textbox(parent, placeholder, initial, callback, width, x, dynamic)
    local b = make("TextBox", {Name = placeholder:gsub("[^%w]", ""), Text = initial or "", PlaceholderText = placeholder,
        PlaceholderColor3 = C.muted, ClearTextOnFocus = false, Size = UDim2.new(width or 1, width and -5 or 0, 0, 42),
        Position = UDim2.new(x or 0, 0, 0, 0), BackgroundColor3 = C.raised, BorderSizePixel = 0,
        TextColor3 = C.text, TextSize = 13, Font = Enum.Font.Gotham, ZIndex = parent.ZIndex + 1}, parent)
    corners(b, 7); outline(b)
    if callback then self:connect(b.FocusLost, function(enter) callback(b.Text, enter) end, dynamic) end
    return b
end

function UI:section(parent, title)
    local t = label(parent, title, 26, 12)
    t.TextColor3 = C.cyan
    t.Font = Enum.Font.GothamBold
    return t
end

function UI:row(parent, buttons)
    local r = frame(parent, 44)
    for i, entry in ipairs(buttons) do
        self:button(r, entry[1], entry[2], 1 / #buttons, (i - 1) / #buttons, entry[3])
    end
    return r
end

function UI:toggle(parent, title, key, default)
    local b
    b = self:button(parent, "", function()
        local value = self.app.preferences[key]
        if value == nil then value = default or false end
        self.app:setPreference(key, not value)
    end)
    table.insert(self.toggles, {button = b, title = title, key = key, default = default})
    return b
end

function UI:refreshToggles()
    for _, entry in ipairs(self.toggles) do
        local value = self.app.preferences[entry.key]
        if value == nil then value = entry.default or false end
        entry.button.Text = (value and "✓  " or "○  ") .. entry.title
        entry.button.TextColor3 = value and C.cyan or C.muted
    end
end

function UI:modal(title, message, text, actionText, action)
    if self.app.input then self.app.input:cancel() end
    self:closeModal()
    local viewW, viewH = self:viewport()
    local inset = self.launcherInset or {top = 8, bottom = 8}
    local compact = viewH < 420
    local dialogW = math.max(160, math.min(600, viewW - 24))
    local dialogH = math.max(160, math.min(600, viewH - inset.top - inset.bottom - 16))
    local shield = make("TextButton", {Name = "DialogShield", Text = "", AutoButtonColor = false, BackgroundColor3 = Color3.new(0, 0, 0),
        BackgroundTransparency = .25, Size = UDim2.fromScale(1, 1), ZIndex = 70}, self.gui)
    local card = make("Frame", {Name = "Dialog", BackgroundColor3 = C.surface, BorderSizePixel = 0,
        AnchorPoint = Vector2.new(.5, .5), Position = UDim2.fromOffset(viewW / 2, inset.top + (viewH - inset.top - inset.bottom) / 2), Size = UDim2.fromOffset(dialogW, dialogH), ZIndex = 71}, shield)
    make("UISizeConstraint", {MaxSize = Vector2.new(600, 600), MinSize = Vector2.new(160, 160)}, card)
    corners(card, 12); outline(card, C.cyan)
    local heading = label(card, title, 32, 17)
    heading.Position = UDim2.new(0, 14, 0, compact and 6 or 10); heading.Size = UDim2.new(1, -28, 0, compact and 28 or 32); heading.ZIndex = 72
    local desc = label(card, message, 68, 12)
    desc.Position = UDim2.new(0, 14, 0, compact and 36 or 48); desc.Size = UDim2.new(1, -28, 0, compact and 40 or 68); desc.ZIndex = 72
    if compact then desc.TextSize = 10 end
    local content = make("ScrollingFrame", {BackgroundColor3 = C.raised, BorderSizePixel = 0, ScrollBarThickness = 5,
        Position = UDim2.new(0, 14, 0, compact and 80 or 120), Size = UDim2.new(1, -28, 1, compact and -144 or -188), CanvasSize = UDim2.new(),
        AutomaticCanvasSize = Enum.AutomaticSize.Y, ZIndex = 72}, card)
    local box = make("TextBox", {Text = text or "", ClearTextOnFocus = false, MultiLine = true, TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, Font = Enum.Font.Code,
        TextColor3 = C.text, TextSize = 13, BackgroundTransparency = 1, Size = UDim2.new(1, -10, 0, 100),
        AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 73}, content)
    local actions = frame(card, 44)
    actions.Position = UDim2.new(0, 14, 1, -56); actions.Size = UDim2.new(1, -28, 0, 44); actions.ZIndex = 73
    self.modalGui, self.modalConnections, self.modalOpen = shield, {}, true
    self:button(actions, "Close", function() self:closeModal() end, .45, 0, nil, self.modalConnections)
    if action then
        self:button(actions, actionText or "Continue", function()
            local ok, result = action(box.Text)
            if ok ~= false then self:closeModal()
            elseif result then
                desc.Text, desc.TextColor3 = tostring(result), C.warning
                self.app:status(result)
            end
        end, .55, .45, C.raised, self.modalConnections)
    end
    return box
end

function UI:confirm(title, message, callback)
    return self:modal(title, message .. "\nThis action requires confirmation.", "", "Confirm", function() callback(); return true end)
end

function UI:closeModal()
    for _, c in ipairs(self.modalConnections or {}) do c:Disconnect() end
    self.modalConnections, self.modalOpen = {}, false
    if self.modalGui then self.modalGui:Destroy(); self.modalGui = nil end
end

